package com.casegen.ai.proposal.review;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.casegen.ai.message.domain.*;
import com.casegen.ai.message.repository.AiMessageRepository;
import com.casegen.ai.provider.*;
import com.casegen.ai.session.domain.AiSession;
import com.casegen.modeling.domain.UmlModel;
import com.casegen.project.domain.Project;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.json.JsonMapper;
class AiProposalBatchGeneratorTest {
 @Test void validatesSourceBuildsWholeSnapshotCallsSelectedProviderAndReturnsItsAudit(){UUID projectId=UUID.randomUUID(),sessionId=UUID.randomUUID(),messageId=UUID.randomUUID(),modelId=UUID.randomUUID();AiMessage source=mock(AiMessage.class);AiSession session=mock(AiSession.class);Project project=mock(Project.class);UmlModel model=mock(UmlModel.class);when(source.getRole()).thenReturn(AiMessageRole.ASSISTANT);when(source.getSkill()).thenReturn(AiSkill.UML_REVIEWER);when(source.getProvider()).thenReturn("OLLAMA");when(source.getId()).thenReturn(messageId);when(source.getSession()).thenReturn(session);when(source.getModel()).thenReturn(model);when(source.getContent()).thenReturn("Review");when(session.getId()).thenReturn(sessionId);when(session.getProject()).thenReturn(project);when(project.getId()).thenReturn(projectId);when(model.getId()).thenReturn(modelId);AiMessageRepository messages=mock(AiMessageRepository.class);when(messages.findDetailedById(messageId)).thenReturn(Optional.of(source));AiUmlReviewSnapshotBuilder snapshots=mock(AiUmlReviewSnapshotBuilder.class);AiUmlReviewSnapshot snapshot=new AiUmlReviewSnapshot(projectId,"P",modelId,"M",1,null,false,new AiUmlReviewSnapshot.Counts(0,0,0,0,0),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of());when(snapshots.build(projectId,modelId,null)).thenReturn(snapshot);SelectedAiProvider provider=mock(SelectedAiProvider.class);when(provider.generate(any())).thenReturn(new AiProviderResult(single(),"GEMINI","gemini-model","STOP"));AiProposalBatchGenerator generator=new AiProposalBatchGenerator(messages,snapshots,new AiProposalBatchPromptBuilder(JsonMapper.builder().build()),provider,new AiReviewResultParser(JsonMapper.builder().build()));GeneratedAiReview generated=generator.generate(new GenerateAiReviewCommand(projectId,sessionId,messageId));assertEquals("GEMINI",generated.review().generatedByProvider());assertEquals(1,generated.review().items().size());assertEquals(1,generated.baseModelRevision());assertEquals(messageId,generated.sourceMessageId());verify(snapshots).build(projectId,modelId,null);verify(provider).generate(any());}
 @Test void rejectsNonReviewerBeforeProvider(){AiMessage source=mock(AiMessage.class);when(source.getRole()).thenReturn(AiMessageRole.USER);AiMessageRepository messages=mock(AiMessageRepository.class);UUID id=UUID.randomUUID();when(messages.findDetailedById(id)).thenReturn(Optional.of(source));SelectedAiProvider provider=mock(SelectedAiProvider.class);AiProposalBatchGenerator generator=new AiProposalBatchGenerator(messages,mock(AiUmlReviewSnapshotBuilder.class),mock(AiProposalBatchPromptBuilder.class),provider,mock(AiReviewResultParser.class));assertThrows(AiReviewGenerationException.class,()->generator.generate(new GenerateAiReviewCommand(UUID.randomUUID(),UUID.randomUUID(),id)));verifyNoInteractions(provider);}
 private String single(){return "{\"reviewTitle\":\"Review\",\"summary\":\"Summary\",\"items\":[{\"clientRef\":\"product\",\"proposalType\":\"ADD_CLASSIFIER\",\"title\":\"Product\",\"rationale\":\"Needed\",\"dependencies\":[],\"payload\":{\"name\":\"Product\",\"documentation\":null,\"packageId\":null,\"kind\":\"CLASS\",\"visibility\":\"PUBLIC\",\"abstractClassifier\":false,\"active\":false}}]}";}
}
